Get-Content -LiteralPath '.env' | ForEach-Object {
  if ($_ -match '^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=(.*)$') { $cfg[$matches[1]] = $matches[2].Trim().Trim('"').Trim("'") }
}
$remoteScript = @'
set -euo pipefail
docker image ls --format '{{.Repository}}:{{.Tag}}' | grep -E '(^gradle:|^node:|ji-stage2)' || true
'@
$remoteScript | & ssh -i $cfg['JI_TEST_SSH_KEY'] -o BatchMode=yes -o StrictHostKeyChecking=yes -- $cfg['JI_TEST_SSH_TARGET'] 'bash -s'
if ($LASTEXITCODE -ne 0) { throw "Remote image inventory failed: $LASTEXITCODE" }

