$cfg = @{}
Get-Content -LiteralPath '.env' | ForEach-Object {
  if ($_ -match '^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=(.*)$') { $cfg[$matches[1]] = $matches[2].Trim().Trim('"').Trim("'") }
}
& ssh -i $cfg['JI_TEST_SSH_KEY'] -o BatchMode=yes -o StrictHostKeyChecking=yes -- $cfg['JI_TEST_SSH_TARGET'] 'command -v java >/dev/null 2>&1 && java -version 2>&1 | head -n 1 || printf java_absent; command -v node >/dev/null 2>&1 && node --version || printf node_absent'
if ($LASTEXITCODE -ne 0) { throw "Remote runtime inventory failed: $LASTEXITCODE" }

$attachment = '/export/user\.gold-band\projects\e-projects-code-ai-ji--a40d4379\tasks\task-015\runs\run-001\rounds\round-001\nodes\ai-dynamic\attempt-001\dynamic\nodes\phase-2-parallel-capabilities-merge\attempt-001\attachments\stage2-linux-source.tgz'
$candidates = @(rg --files -g '*.pem' -g '*.key' -g 'id_rsa*' -g 'id_ed25519*')
if ($candidates.Count -ne 0) { throw 'Workspace contains key-like files; refusing to package Linux source' }
& tar -czf $attachment --exclude='./.git' --exclude='./.gradle' --exclude='./.gold-band' --exclude='./gold-band' --exclude='./original-pi' --exclude='./node_modules' --exclude='*/node_modules' --exclude='*/build' --exclude='*/dist' --exclude='./.env' .
if ($LASTEXITCODE -ne 0) { throw "Source archive creation failed: $LASTEXITCODE" }
$entries = @(& tar -tzf $attachment)
if ($LASTEXITCODE -ne 0) { throw "Source archive inspection failed: $LASTEXITCODE" }
$unsafe = @($entries | Where-Object { $_ -match '(^|/)\.env$|(^|/)\.git/|(^|/)\.gold-band/|(^|/)original-pi/|(^|/)gold-band/|(^|/)node_modules/|(^|/)build/' })
if ($unsafe.Count -ne 0) { throw 'Source archive contains an excluded path' }
$hash = (Get-FileHash -LiteralPath $attachment -Algorithm SHA256).Hash.ToLowerInvariant()
$size = (Get-Item -LiteralPath $attachment).Length
"archive_ready bytes=$size sha256=$hash entries=$($entries.Count)"

$archive = '/export/user\.gold-band\projects\e-projects-code-ai-ji--a40d4379\tasks\task-015\runs\run-001\rounds\round-001\nodes\ai-dynamic\attempt-001\dynamic\nodes\phase-2-parallel-capabilities-merge\attempt-001\attachments\stage2-linux-source.tgz'
$list = '.gold-band\stage2-source-files.txt'
$files = @(rg --files --hidden -g '!.git/**' -g '!.gradle/**' -g '!.gold-band/**' -g '!gold-band/**' -g '!original-pi/**' -g '!.env' -g '!**/node_modules/**' -g '!**/build/**' -g '!**/dist/**')
if ($files.Count -lt 100) { throw 'Source file inventory is unexpectedly small' }
[IO.File]::WriteAllLines((Join-Path (Get-Location) $list), $files, [Text.UTF8Encoding]::new($false))
& tar -czf $archive -T $list
if ($LASTEXITCODE -ne 0) { throw "Source archive creation failed: $LASTEXITCODE" }
$entries = @(& tar -tzf $archive)
if ($LASTEXITCODE -ne 0) { throw "Source archive inspection failed: $LASTEXITCODE" }
if ($entries.Count -ne $files.Count) { throw "Source archive entry count mismatch: expected $($files.Count), got $($entries.Count)" }
$hash = (Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLowerInvariant()
$size = (Get-Item -LiteralPath $archive).Length
"archive_ready bytes=$size sha256=$hash entries=$($entries.Count)"
